/**
 * @param {string} s
 * @return {number}
 */
var minFlips = function(s) {
    const n = s.length;
    const dp = new Array(n + 1).fill(0);

    for (let i = 0; i < n; i++) {
        const isEven = i % 2 === 0;
        const isZero = s[i] === '0';

        if (isEven ^ isZero) {
            dp[i + 1] = dp[i] + 1;
        } else {
            dp[i + 1] = dp[i];
        }
    }

    return Math.min(dp[n], n - dp[n]);
};

/**
 * @param {string} s
 * @return {number}
 */
var minFlips = s => {
    const n = s.length;
    const op = [0, 0];
    let res = n;

    for (let i = 0; i < n; i++) {
        op[(s.charCodeAt(i) ^ i) & 1]++;
    }

    for (let i = 0; i < n; i++) {
        const c = s.charCodeAt(i);
        op[(c ^ i) & 1]--;
        op[(c ^ (n + i)) & 1]++;
        res = Math.min(res, ...op);
    }

    return res;
};
